@var x[1:2, 1:2, 1:2, 1:2, 1:2];
vars = reduce(vcat,x[1:2, 1:2, 1:2, 1:2, 1:2]);
@var a[1:2,1:12];
@var b[1:2,1:12];
@var c[1:2,1:12];
@var d[1:2,1:12];
@var e[1:2,1:12];

list2mats = function(L,atmp)
     [stack([[atmp[i,j] for i=1:2] for j in ell]) for ell in L];
end
diffList = function(f,L)
local tmp;
    tmp = f;
    for xx in L tmp = differentiate(tmp,xx);end
tmp        
end
varSymbols = [a,b,c,d,e]
# this function is for 2^5 tensors
unfactor = function(F)
local tmp, deg, L;
    # F is the unsymmetric tensor
# deg is the x-degree of the form
deg = Int(degree(F)/5);
# L is the list of dimensions of vector spaces
L = [2,2,2,2,2];
    tmp = F; @time for dg=1:deg
    tmp = sum([diffList(tmp, [a[i1,dg],b[i2,dg],c[i3,dg],d[i4,dg],e[i5,dg]])*x[i1,i2,i3,i4,i5] for i1=1:L[1], i2=1:L[2], i3=1:L[3], i4=1:L[4], i5=1:L[5]]);
    end
return tmp
end
